function customPanel(){const c=customization[lang];return `<aside class="customization"><div><p class="eyebrow">VICTOR IERMITO · LUTHIER</p><h2>${c.title}</h2><p>${c.text}</p></div><a class="custom-button" href="https://www.instagram.com/victoriermitoluthier/" target="_blank" rel="noopener">${c.button}</a></aside>`}
const modelKeys=['T-1','T-2','T-3','ECO','special','custom'];
const modelPhotos=['assets/hero-illustration.png','assets/hero-illustration.png','assets/guitar.jpg','assets/guitar.jpg','assets/detail.jpg','assets/workshop.jpg'];
const main=document.querySelector('main');
const homeHTML=main.innerHTML;
const recordHTML=document.querySelector('.record').outerHTML;
const originalSetLang=setLang;
let stream=null,scanTimer=null;
function tr(k){return extra[lang][k]}
function modelName(k){return k==='special'?tr('special'):k==='custom'?customization[lang].title:k}
function applyLanguage(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(e=>{if(copy[lang][e.dataset.i])e.innerHTML=copy[lang][e.dataset.i]});document.querySelectorAll('[data-lang]').forEach(e=>e.setAttribute('aria-pressed',e.dataset.lang===lang));const render=rows=>rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('');if(document.querySelector('#specs')){document.querySelector('#specs').innerHTML=render(specs[lang].slice(0,6));document.querySelector('#moreSpecs').innerHTML=render(specs[lang].slice(6))}document.querySelectorAll('[data-x]').forEach(e=>e.innerHTML=tr(e.dataset.x));document.querySelectorAll('nav a')[0].textContent=tr('models');document.querySelector('.sample').textContent=tr('ready');}
function identityPanel(){return `<div class="passport-copy"><p class="eyebrow">VICTOR IERMITO · LUTHIER</p><h2>${tr('identity')}</h2><p>${tr('identityText')}</p></div><div><button type="button" class="scan" id="scanButton">▣ &nbsp; ${tr('scan')}<small>${tr('mobile')}</small></button><div class="or">${tr('or')}</div><form class="lookup" id="serialForm"><label><input aria-label="${tr('series')}" placeholder="${tr('series')}" inputmode="numeric" pattern="[0-9]+" required></label><button>${tr('consult')}</button></form><p id="lookupError" class="error" role="status" hidden></p></div>`}
function renderHome(){main.innerHTML=homeHTML;applyLanguage();document.querySelector('h1').innerHTML=tr('hero').split('<br>').map(line=>`<span>${line}</span>`).join('');document.querySelector('.hero .eyebrow').textContent=tr('modelIntro');document.querySelector('.hero-photo img').src='assets/hero-approved-direction.png';document.querySelector('.hero-photo img').alt=lang==='es'?'Guitarra ilustrativa para la muestra':lang==='fr'?'Guitare illustrative pour la démonstration':'Illustrative guitar for the demo';document.querySelector('.caption').textContent=tr('demo');document.querySelector('.intro').textContent=tr('intro');document.querySelector('.hero .button').href='#/guitars';document.querySelector('.section-top h2').textContent=tr('sound');document.querySelector('.section-top h2').insertAdjacentHTML('afterend',`<p class="subline">${tr('search')}</p>`);document.querySelector('.gallery').innerHTML=`<figure><a href="#/guitars"><img src="assets/hero-illustration.png" alt="${tr('gallery')}" loading="lazy"><figcaption><b>${tr('gallery')}</b></figcaption></a></figure><figure><a href="#details"><img src="assets/detail.jpg" alt="${tr('details')}" loading="lazy"><figcaption><b>${tr('details')}</b></figcaption></a></figure><figure><a href="#atelier"><img src="assets/guitar.jpg" alt="${tr('workshop')}" loading="lazy"><figcaption><b>${tr('workshop')}</b></figcaption></a></figure>`;document.querySelector('.atelier').insertAdjacentHTML('afterend',`<section id="details" class="section detail-story"><p class="eyebrow">${tr('details')}</p><h2>${tr('sound')}</h2><p class="subline">${tr('search')}</p><div class="detail-pictures"><img src="assets/detail.jpg" alt="${tr('details')}" loading="lazy"><img src="assets/workshop.jpg" alt="${tr('details')}" loading="lazy"></div></section>`);document.querySelector('.atelier img').src='assets/guitar.jpg';document.querySelector('.passport .section').innerHTML=identityPanel();document.querySelector('.passport').insertAdjacentHTML('beforebegin',`<section class="section listen" id="listen"><div><p class="eyebrow">VICTOR IERMITO</p><h2>${tr('listen')}</h2><p>${tr('listenText')}</p></div><a class="button" target="_blank" rel="noopener" href="https://www.youtube.com/watch?v=tmihgvj4r5w&t=1s">▷ &nbsp; ${tr('video')}</a></section>`);document.querySelector('#serialForm').onsubmit=submitSerial;document.querySelector('#scanButton').onclick=startCamera;}
function modelCard(k,i){return `<a class="modelcard" id="model-${k}" href="#/guitars/${k}"><div class="modelpic"><img src="${modelPhotos[i]}" alt="${modelName(k)} — ${tr('demo')}" loading="lazy" style="object-position:${i===1?'40% 50%':'50% 50%'}"></div><div><div class="modelmeta"><h2>${modelName(k)}</h2><span>↗</span></div><p>${tr('discover')}</p></div></a>`}
function renderModels(){main.innerHTML=`<section class="models-page"><a class="breadcrumbs" href="#/">${tr('back')} / ${tr('models')}</a><p class="eyebrow">${tr('collection')}</p><div class="models-intro"><h1>${tr('collectionTitle')}</h1><p>${tr('collectionText')}</p></div><nav class="modelnav" aria-label="${tr('collection')}">${modelKeys.map(k=>`<a href="#/guitars/${k}">${modelName(k)} ↗</a>`).join('')}</nav><div class="modelgrid">${modelKeys.map(modelCard).join('')}</div><p class="image-note">${tr('demo')}</p></section>`;applyLanguage();}
function renderModel(k){const i=modelKeys.indexOf(k);if(i<0){location.hash='/guitars';return}main.innerHTML=`<section class="detail-page"><a class="breadcrumbs" href="#/guitars">← ${tr('models')} / ${modelName(k)}</a><div class="detail-layout"><div><img src="${modelPhotos[i]}" alt="${modelName(k)} — ${tr('demo')}"><p class="image-note">${tr('demo')}</p></div><div><p class="eyebrow">${tr('modelIntro')}</p><h1>${modelName(k)}</h1><p>${k==='custom'?customization[lang].text:tr(k==='special'?'specialDesc':k==='ECO'?'ecoDesc':'tDesc')}</p><div class="pending"><p>${tr('pending')}</p></div><a class="button" href="https://www.instagram.com/victoriermitoluthier/" target="_blank" rel="noopener">${tr('ask')}</a></div></div><p class="eyebrow" style="margin-top:60px">${tr('others')}</p><div class="model-list">${modelKeys.filter(x=>x!==k).map(x=>`<a class="text-link" href="#/guitars/${x}">${modelName(x)} ↗</a>`).join('')}</div></section>`;applyLanguage();}
function renderRecord(n){if(n!=='35290'){main.innerHTML=`<section class="recordview"><a class="breadcrumbs" href="#/">← ${tr('recordBack')}</a><h2>${tr('record')}</h2><p>${tr('unknown')}</p><a class="button" href="#/record/35290">35290 ↗</a></section>`;return}main.innerHTML=`<section class="recordview"><a class="breadcrumbs" href="#/">← ${tr('recordBack')}</a><p class="eyebrow">${tr('record')}</p>${recordHTML}</section>`;applyLanguage();document.querySelector('.record-head small').textContent=tr('record');}
function updateNav(){const labels=lang==='es'?['Guitarras','El taller','Escuchar','Tu guitarra','Contacto']:lang==='fr'?['Guitares','L’atelier','Écouter','Votre guitare','Contact']:['Guitars','The workshop','Listen','Your guitar','Contact'];const targets=['#/guitars','#atelier','#listen','#passport','#contact'];document.querySelector('header nav').innerHTML=labels.map((label,i)=>`<a href="${targets[i]}">${label}</a>`).join('');document.querySelector('.brand').href='#/';}
function route(){const h=location.hash.slice(1)||'/';if(['/order','/terms','/legal','/privacy'].includes(h)&&typeof renderPractical==='function')renderPractical(h.slice(1));else if(h==='/press'&&typeof renderPress==='function')renderPress();else if(h==='/projects'&&typeof renderProjects==='function')renderProjects();else if(h.startsWith('/guitars/'))renderModel(decodeURIComponent(h.split('/')[2]));else if(h==='/guitars')renderModels();else if(h.startsWith('/record/'))renderRecord(h.split('/')[2]);else{renderHome();if(h!=='/'){requestAnimationFrame(()=>document.getElementById(h)?.scrollIntoView())}}updateNav();let access=document.querySelector('footer .guitar-access');if(!access){access=document.createElement('a');access.className='guitar-access';access.href='#passport';document.querySelector('footer').prepend(access)}access.textContent=tr('identity')+' ↗';if(h.startsWith('/'))window.scrollTo(0,0);}
function submitSerial(e){e.preventDefault();const n=e.currentTarget.querySelector('input').value.trim();if(n==='35290')location.hash='/record/'+n;else{const el=document.querySelector('#lookupError');el.hidden=false;el.textContent=tr('unknown')}}
const dialog=document.createElement('dialog');dialog.innerHTML='<h2></h2><video playsinline muted autoplay></video><p class="scanStatus" role="status"></p><button type="button"></button>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',stopCamera);dialog.addEventListener('cancel',stopCamera);window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden&&dialog.open)dialog.close()});
function stopCamera(){clearTimeout(scanTimer);if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;dialog.querySelector('video').srcObject=null;}
function parseQR(text){if(/^\d+$/.test(text.trim()))return text.trim();try{const u=new URL(text);if(!['victoriermito.web.app',location.hostname,'victoriermito.com','www.victoriermito.com'].includes(u.hostname))return null;const m=u.pathname.match(/(?:^|\/)(\d+)\/?$/);return m?m[1]:null}catch{return null}}
async function startCamera(){stopCamera();dialog.querySelector('h2').textContent=tr('scan');dialog.querySelector('button').textContent=tr('close');const status=dialog.querySelector('.scanStatus');status.textContent=tr('scanning');dialog.showModal();if(!navigator.mediaDevices?.getUserMedia){status.textContent=tr('noCamera');return}try{const s=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280}}});if(!dialog.open){s.getTracks().forEach(t=>t.stop());return}stream=s;const video=dialog.querySelector('video');video.srcObject=stream;await video.play();status.textContent=tr('camera');const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d',{willReadFrequently:true});const scan=()=>{if(!stream||!dialog.open)return;if(video.readyState>=2&&video.videoWidth){canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);const code=window.jsQR?.(pixels.data,canvas.width,canvas.height,{inversionAttempts:'attemptBoth'});if(code){const n=parseQR(code.data);if(n){dialog.close();location.hash='/record/'+n;return}status.textContent=tr('invalidQR')}}scanTimer=setTimeout(scan,220)};scan()}catch{stopCamera();status.textContent=tr('permission')}}
setLang=function(l){lang=l;try{localStorage.setItem('vi-language',l)}catch{}route()};
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));window.addEventListener('hashchange',route);try{const saved=localStorage.getItem('vi-language');if(extra[saved])lang=saved}catch{}route();
